import { test } from "node:test";
import assert from "node:assert/strict";
import { quoteOrder, type Order } from "../src/delivery/quote.ts";
import { courierPayout } from "../src/delivery/courierPay.ts";
import { checkout } from "../src/delivery/checkout.ts";
import { UnknownZoneError } from "../src/delivery/feeSchedule.ts";

let seq = 0;
const order = (zone: string, subtotalCents: number): Order => ({
    id: `o${++seq}`,
    zone,
    lines: [{ sku: "bifana", unitCents: subtotalCents / 2, qty: 2 }],
});

function fakeGateway() {
    const charges: [string, number][] = [];
    return { charges, charge: async (id: string, cents: number) => void charges.push([id, cents]) };
}

test("a small basket pays delivery, the minimum service fee and the small-order fee", () => {
    assert.deepEqual(quoteOrder(order("lis-centro", 900)), {
        subtotalCents: 900,
        deliveryCents: 299,
        serviceCents: 99,
        smallOrderCents: 150,
        totalCents: 1448,
    });
});

test("surge raises the delivery fee during a busy period", () => {
    const q = quoteOrder(order("lis-oriente", 2000), 1.5);
    assert.equal(q.deliveryCents, 599);
    assert.equal(q.totalCents, 2000 + 599 + 240);
});

test("the next order after a busy period pays the normal delivery fee", () => {
    quoteOrder(order("lis-oriente", 2000), 1.5);
    const calm = quoteOrder(order("lis-oriente", 2000), 1);
    console.log("delivery fee once the surge is over:", calm.deliveryCents, "(standard is 399)");
    assert.equal(calm.deliveryCents, 399);
});

test("free delivery on a big basket doesn't carry over to the next customer's small basket", () => {
    assert.equal(quoteOrder(order("lis-centro", 3500)).deliveryCents, 0);
    const small = quoteOrder(order("lis-centro", 900));
    assert.deepEqual([small.deliveryCents, small.smallOrderCents, small.totalCents], [299, 150, 1448]);
});

test("unknown zones, empty orders and silly surge values are rejected", () => {
    assert.throws(() => quoteOrder(order("porto-baixa", 1000)), UnknownZoneError);
    assert.throws(() => quoteOrder({ id: "e", zone: "lis-centro", lines: [] }), /empty/);
    assert.throws(() => quoteOrder(order("lis-centro", 1000), 0.5), /out of range/);
});

test("a free-delivery order still pays the courier their share of the standard fee", async () => {
    const gateway = fakeGateway();
    const s = await checkout(gateway, order("lis-centro", 3500), 1, 100);
    assert.deepEqual(gateway.charges, [[s.orderId, 3950]]);
    assert.equal(s.courierCents, 239 + 100);
    assert.equal(s.platformCents, 3950 - 3500 - 339);
});

test("courier surge bonus is computed on the standard fee, however many surge quotes came before", () => {
    for (let i = 0; i < 3; i++) quoteOrder(order("lis-oriente", 1500), 2);
    assert.equal(courierPayout({ orderId: "x", zone: "lis-oriente", tipCents: 0, surge: 2 }), 299 * 2);
    assert.equal(courierPayout({ orderId: "y", zone: "lis-oriente", tipCents: 50, surge: 1 }), 299 + 50);
});
